@Override
public boolean equals(Object o) {
    if (this == o) {
        return true;
    }
    if (o == null || getClass() != o.getClass()) {
        return false;
    }
    MetricId metricId = (MetricId) o;
    return Objects.equals(metricName, metricId.metricName) && Objects.equals(values, metricId.values);
}
